//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient errors that may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_classified_transient() {
        assert!(RetryError::Transient("blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_transient() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a new retry configuration.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Delay in milliseconds before the retry with the given 0-based index.
    ///
    /// The delay doubles on every retry, starting at `base_delay_ms`, and
    /// saturates at `max_delay_ms` once the exponential growth would exceed
    /// it (or overflow `u64`).
    pub fn retry_delay_ms(&self, retry_index: u32) -> u64 {
        // 2^retry_index, capped so the multiplication can never overflow.
        let multiplier = 1u64.checked_shl(retry_index).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_starts_at_base_and_doubles() {
        let config = RetryConfig::new(6, 10, 10_000);
        assert_eq!(config.retry_delay_ms(0), 10);
        assert_eq!(config.retry_delay_ms(1), 20);
        assert_eq!(config.retry_delay_ms(2), 40);
        assert_eq!(config.retry_delay_ms(3), 80);
        assert_eq!(config.retry_delay_ms(4), 160);
        assert_eq!(config.retry_delay_ms(5), 320);
    }

    #[test]
    fn delay_saturates_at_max_delay_ms() {
        let config = RetryConfig::new(100, 10, 150);
        assert_eq!(config.retry_delay_ms(0), 10);
        assert_eq!(config.retry_delay_ms(3), 80);
        assert_eq!(config.retry_delay_ms(4), 150);
        assert_eq!(config.retry_delay_ms(10), 150);
        assert_eq!(config.retry_delay_ms(99), 150);
    }

    #[test]
    fn delay_never_overflows_u64() {
        let config = RetryConfig::new(u32::MAX, u64::MAX, 100);
        assert_eq!(config.retry_delay_ms(u32::MAX), 100);
        assert_eq!(config.retry_delay_ms(63), 100);
        assert_eq!(config.retry_delay_ms(64), 100);
    }

    #[test]
    fn max_delay_below_base_is_capped_immediately() {
        let config = RetryConfig::new(3, 1000, 100);
        assert_eq!(config.retry_delay_ms(0), 100);
        assert_eq!(config.retry_delay_ms(1), 100);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
///
/// The retry policy is a bounded exponential backoff:
/// - `max_attempts` includes the first call (`1` disables retries);
/// - only [`RetryError::Transient`] errors are retried; a permanent
///   error returns immediately;
/// - the delay before the first retry is `base_delay_ms`, doubling on
///   every retry and saturating at `max_delay_ms`.
///
/// Returns `Ok(())` on success, a permanent error as soon as it occurs,
/// or the last transient error once the attempt budget is exhausted.
///
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    debug_assert!(config.max_attempts >= 1, "max_attempts must be >= 1");
    let mut attempts = 0u32;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                attempts += 1;
                if attempts >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.retry_delay_ms(attempts - 1));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)
    }

    #[test]
    fn succeeds_on_first_attempt_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3, 10, 100), &mut sleeper, || Ok(()));
        assert_eq!(result, Ok(()));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient(format!("blip {calls}")))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn stops_after_max_attempts_and_returns_last_error() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient(format!("blip {calls}")))
        });
        assert_eq!(result, Err(RetryError::Transient("blip 3".to_string())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn max_attempts_one_never_retries() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(1, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("blip".to_string()))
        });
        assert_eq!(result, Err(RetryError::Transient("blip".to_string())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_returns_immediately() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".to_string()))
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_after_transient_attempts_is_not_retried() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            if calls == 1 {
                Err(RetryError::Transient("blip".to_string()))
            } else {
                Err(RetryError::Permanent("bad input".to_string()))
            }
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }

    #[test]
    fn delays_grow_exponentially_and_saturate_at_max_delay_ms() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(6, 10, 30), &mut sleeper, || {
            Err(RetryError::Transient("flaky".to_string()))
        });
        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![10, 20, 30, 30, 30]);
    }
}

//! Integration coverage for the bounded exponential retry policy,
//! exercised through the public API only.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_only_transient_errors_until_success() {
    let config = RetryConfig::new(4, 5, 50);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 1 {
            Err(RetryError::Transient("temporary lock".to_string()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

#[test]
fn public_api_exhausts_budget_and_returns_last_transient_error() {
    let config = RetryConfig::new(3, 10, 1000);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("still down".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("still down".to_string())));
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn public_api_max_attempts_one_means_no_retries() {
    let config = RetryConfig::new(1, 10, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".to_string()))
    });
    assert!(result.is_err());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn public_api_permanent_error_returns_immediately() {
    let config = RetryConfig::new(10, 10, 1000);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".to_string()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn public_api_saturates_delays_at_max_delay_ms() {
    let config = RetryConfig::new(5, 10, 25);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("flaky".to_string()))
    });
    assert!(result.is_err());
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}
